import{_ as d,C as e,o as s,c as l,j as t,E as o,a as r,a2 as n}from"./chunks/framework.C21TwvGF.js";const q=JSON.parse(`{"title":"3-hafta (Mentor)","description":"","frontmatter":{"title":"3-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"11-sinf","link":"/mentor/11-sinf/"},"n":3,"bob":"I-bob · Dasturiy ta'minot ishlab chiqish asoslari","lessons":[{"g":7,"title":"Clean Code asoslari va SOLID: SRP hamda OCP tamoyillari","lead":"Professional kod madaniyati, to'g'ri nomlash, DRY/KISS/YAGNI tamoyillari hamda barqaror arxitektura poydevori: SRP va OCP.","link":"/mentor/11-sinf/hafta-03/dars-1","slide":"/slaydlar/11-sinf/hafta-03/dars-1.html","test":"/slaydlar/11-sinf/hafta-03/dars-1-test.html"},{"g":8,"title":"SOLID chuqurlashtirilgan: LSP, ISP, DIP va Code Smells refaktoringi","lead":"Liskov almashinish qoidasi, ixcham interfeyslar, Dependency Injection kuchi va yomon arxitektura alomatlarini (Code Smells) davolash.","link":"/mentor/11-sinf/hafta-03/dars-2","slide":"/slaydlar/11-sinf/hafta-03/dars-2.html","test":"/slaydlar/11-sinf/hafta-03/dars-2-test.html"},{"g":9,"title":"Loyihalash andozalari: Factory va Singleton arxitekturasi","lead":"Creational patterns: Factory Method yordamida obyekt yaratishni markazlashtirish, Singleton kuchi va global holat xatarlari.","link":"/mentor/11-sinf/hafta-03/dars-3","slide":"/slaydlar/11-sinf/hafta-03/dars-3.html","test":"/slaydlar/11-sinf/hafta-03/dars-3-test.html"}],"test":"/slaydlar/11-sinf/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"mentor/11-sinf/hafta-03/index.md","filePath":"mentor/11-sinf/hafta-03/index.md"}`),h={name:"mentor/11-sinf/hafta-03/index.md"},c={class:"blk"},g={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},u={class:"blk"},m={id:"baholash-mezoni",tabindex:"-1"};function y(_,a,f,b,v,p){const i=e("Icon");return s(),l("div",null,[t("div",c,[t("h2",g,[o(i,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=t("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=n('<p>Har bir vazifa 20–30 daqiqa. Parol, shaxsiy token, maxfiy kalit va shaxsiy ma&#39;lumotlarni repozitoriyga yozmang: topshirishda faqat ochiq GitHub repo yoki Pull Request havolasi kerak.</p><h2 id="_7-dars-uchun-clean-code-srp-va-ocp" tabindex="-1">7-dars uchun (Clean Code, SRP va OCP) <a class="header-anchor" href="#_7-dars-uchun-clean-code-srp-va-ocp" aria-label="Permalink to &quot;7-dars uchun (Clean Code, SRP va OCP)&quot;">​</a></h2><p><strong>1-topshiriq: «Kodni tozalash va OCP kengaytirish»</strong></p><ol><li>O&#39;z GitHub portfolio repozitoriyangizda yangi <code>refactor/clean-code</code> tarmog&#39;ini oching.</li><li><code>order_processor.py</code> nomli fayl yarating. Unga kamida 30 qatordan iborat «Spaghetti» kod (hisoblash, chegirma, soliq, xabar jo&#39;natish bitta funksiyada) yozing.</li><li>Ushbu kodni Clean Code qoidalari asosida tozalang: <ul><li>Funksiyalarni bo&#39;ling (<code>Extract Method</code>);</li><li>Mas&#39;uliyatlarni alohida sinflarga ajrating (<code>SRP</code>);</li><li><code>PaymentProcessor</code> abstrakt sinfi (<code>abc.ABC</code>) orqali to&#39;lov turlarini OCP talablariga moslang.</li></ul></li><li>O&#39;zgarishlarni semantik commitlar (<code>refactor(core): apply SRP and OCP to order processor</code>) bilan saqlab, GitHub&#39;ga push qiling.</li></ol><p><strong>Kutiladigan natija:</strong> tushunarli nomlangan, SRP va OCP tamoyillariga javob beradigan toza Python moduli.<br><strong>Topshirish:</strong> GitHub commit yoki fayl havolasi.</p><hr><h2 id="_8-dars-uchun-lsp-isp-dip-va-unit-test" tabindex="-1">8-dars uchun (LSP, ISP, DIP va Unit Test) <a class="header-anchor" href="#_8-dars-uchun-lsp-isp-dip-va-unit-test" aria-label="Permalink to &quot;8-dars uchun (LSP, ISP, DIP va Unit Test)&quot;">​</a></h2><p><strong>2-topshiriq: «Dependency Injection va Bazasiz Unit Test»</strong></p><ol><li><code>service_architecture.py</code> faylida <code>UserRepository</code> abstrakt interfeysini e&#39;lon qiling (<code>get_user(id)</code>, <code>save_user(user)</code>).</li><li>Ushbu interfeysga tayanuvchi <code>UserService</code> biznes mantiq sinfini yozing (Dependency Injection orqali repositoriyani qabul qilsin).</li><li>Testlar uchun xotirada ishlovchi <code>FakeUserRepository</code> (oddiy Python <code>dict</code> orqali) sinfini yozing.</li><li><code>test_user_service.py</code> faylida hech qanday PostgreSQL yoki tashqi serverga ulanmasdan <code>pytest</code> yoki oddiy <code>assert</code> orqali 3 ta test yozing (foydalanuvchi topilishi, yangi foydalanuvchi qo&#39;shilishi, topilmaganda xatolik).</li></ol><p><strong>Kutiladigan natija:</strong> DIP va DI tufayli 100% mustaqil, 0.01 soniyada yashil o&#39;tuvchi unit-testlar to&#39;plami.<br><strong>Topshirish:</strong> GitHub tarmog&#39;i va testlarning terminaldagi muvaffaqiyatli skrinshoti.</p><hr><h2 id="_9-dars-uchun-factory-va-singleton-andozalari" tabindex="-1">9-dars uchun (Factory va Singleton andozalari) <a class="header-anchor" href="#_9-dars-uchun-factory-va-singleton-andozalari" aria-label="Permalink to &quot;9-dars uchun (Factory va Singleton andozalari)&quot;">​</a></h2><p><strong>3-topshiriq: «Loyiha ConfigManager Singleton va Logger»</strong></p><ol><li><code>patterns.py</code> faylida <code>__new__</code> metodi yordamida <code>AppConfig</code> nomli Singleton sinfini tuzing. U dastur sozlamalarini (masalan: <code>APP_NAME</code>, <code>DEBUG</code>, <code>PORT</code>) faqat bir marta xotiraga yuklasin.</li><li>Ikkita alohida joyda <code>cfg1 = AppConfig()</code> va <code>cfg2 = AppConfig()</code> deb chaqirib, <code>cfg1 is cfg2</code> natijasi <code>True</code> ekanini <code>assert</code> bilan tasdiqlang.</li><li>Xabarnomalar tizimi uchun <code>NotificationFactory</code> yarating (<code>email</code>, <code>sms</code>, <code>telegram</code> turlari bo&#39;yicha mos obyektlarni qaytarsin). Noma&#39;lum tur kiritilganda <code>ValueError</code> tashlashini ta&#39;minlang.</li><li>Hammasini <code>main</code> tarmog&#39;iga Pull Request qilib yuboring.</li></ol><p><strong>Kutiladigan natija:</strong> Singleton va Factory andozalari to&#39;g&#39;ri tatbiq etilgan, to&#39;liq testlangan Python kodi.<br><strong>Topshirish:</strong> GitHub Pull Request havolasi.</p><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><p>Dars boshida o&#39;quvchining OCP yechimini ko&#39;zdan kechiring: yangi to&#39;lov turi qo&#39;shilganda haqiqatan ham eski kodga tegilmaganini tekshiring. 8-dars topshirig&#39;ida <code>UserService</code> ichida <code>FakeUserRepository()</code> to&#39;g&#39;ridan-to&#39;g&#39;ri yaratilmaganiga (faqat konstruktor parametri orqali kiritilganiga) ishonch hosil qiling. Singleton kodida <code>__new__</code> va <code>_instance</code> to&#39;g&#39;ri ishlatilganini tahlil qiling.</p>',18))]),t("div",u,[t("h2",m,[o(i,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=t("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=n('<p>Bitta o&#39;quvchi uchun shablon. Maqsad: haftalar bo&#39;yicha o&#39;sish dinamikasini kuzatish. Har hafta shu shablon nusxalanib, «Dinamika» jadvaliga bitta qator qo&#39;shiladi.</p><p><strong>O&#39;quvchi:</strong> ____________________ <strong>Guruh/sinf:</strong> 11-sinf <strong>Mentor:</strong> ____________________</p><h2 id="shkala-va-mezonlar-o-quv-dasturi-8-bo-lim" tabindex="-1">Shkala va mezonlar (o&#39;quv dasturi, 8-bo&#39;lim) <a class="header-anchor" href="#shkala-va-mezonlar-o-quv-dasturi-8-bo-lim" aria-label="Permalink to &quot;Shkala va mezonlar (o&#39;quv dasturi, 8-bo&#39;lim)&quot;">​</a></h2><p>100 ballik shkala: <strong>90–100 — 5 (a&#39;lo)</strong>, <strong>71–89 — 4 (yaxshi)</strong>, <strong>60–70 — 3 (qoniqarli)</strong>, <strong>0–59 — 2 (qoniqarsiz)</strong>.</p><p>Dasturdagi mezonlar: mavzu bo&#39;yicha tasavvurga ega bo&#39;lish; mavzu mohiyatini tushunish va aytib bera olish; bilimni amalda qo&#39;llash; ijodiy fikrlash va xulosa chiqarish; mustaqil ish bajarish.</p><table tabindex="0"><thead><tr><th>Mezon</th><th>Max</th></tr></thead><tbody><tr><td>Mohiyatni tushunadi va aytib bera oladi (tezkor nazorat, og&#39;zaki)</td><td>30</td></tr><tr><td>Amaliy topshiriq: to&#39;g&#39;ri va to&#39;liq, mustaqil bajarilgan</td><td>30</td></tr><tr><td>Ish sifati: toza arxitektura, SOLID tamoyillari, testlar mavjudligi</td><td>20</td></tr><tr><td>Uyga vazifa bajarilgan va o&#39;z vaqtida topshirilgan</td><td>20</td></tr><tr><td><strong>Jami</strong></td><td><strong>100</strong></td></tr></tbody></table><hr><h2 id="_7-dars-clean-code-va-solid-srp-hamda-ocp" tabindex="-1">7-dars. Clean Code va SOLID: SRP hamda OCP <a class="header-anchor" href="#_7-dars-clean-code-va-solid-srp-hamda-ocp" aria-label="Permalink to &quot;7-dars. Clean Code va SOLID: SRP hamda OCP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Nimaga qaraladi</th><th>Ball</th></tr></thead><tbody><tr><td>Tezkor nazorat /30</td><td>DRY/KISS/YAGNI mohiyati; nomlash odobi; SRP va OCP qoidalarini izohlay olishi</td><td></td></tr><tr><td>Amaliyot /30</td><td>Spaghetti funksiyani Extract Method bilan bo&#39;lish; mas&#39;uliyatlarni alohida sinflarga ajratish</td><td></td></tr><tr><td>Ish sifati /20</td><td><code>abc.ABC</code> orqali to&#39;g&#39;ri abstraksiya; yangi to&#39;lov sinfi qo&#39;shilganda asosiy kod o&#39;zgarmasligi</td><td></td></tr><tr><td>Uyga vazifa /20</td><td><code>order_processor.py</code> to&#39;liq refaktoring qilingan; GitHub tarmog&#39;ida Conventional Commitlar</td><td></td></tr><tr><td><strong>Jami /100</strong></td><td></td><td></td></tr></tbody></table><p>Izoh: ____________________</p><hr><h2 id="_8-dars-solid-lsp-isp-dip-va-refaktoring" tabindex="-1">8-dars. SOLID: LSP, ISP, DIP va Refaktoring <a class="header-anchor" href="#_8-dars-solid-lsp-isp-dip-va-refaktoring" aria-label="Permalink to &quot;8-dars. SOLID: LSP, ISP, DIP va Refaktoring&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Nimaga qaraladi</th><th>Ball</th></tr></thead><tbody><tr><td>Tezkor nazorat /30</td><td>LSP va voris sinf kafolati; ISP bo&#39;yicha kichik interfeyslar; DIP va DI farqi</td><td></td></tr><tr><td>Amaliyot /30</td><td><code>UserRepository</code> interfeysini qurish; <code>UserService</code>ga Dependency Injection qo&#39;llash</td><td></td></tr><tr><td>Ish sifati /20</td><td>Bazasiz (in-memory mock) unit-test yozilgani; Code Smell&#39;lar to&#39;g&#39;ri aniqlangani</td><td></td></tr><tr><td>Uyga vazifa /20</td><td><code>test_user_service.py</code> to&#39;liq o&#39;tgan; mustaqil test natijalari mavjud</td><td></td></tr><tr><td><strong>Jami /100</strong></td><td></td><td></td></tr></tbody></table><p>Izoh: ____________________</p><hr><h2 id="_9-dars-loyihalash-andozalari-factory-va-singleton" tabindex="-1">9-dars. Loyihalash andozalari: Factory va Singleton <a class="header-anchor" href="#_9-dars-loyihalash-andozalari-factory-va-singleton" aria-label="Permalink to &quot;9-dars. Loyihalash andozalari: Factory va Singleton&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Nimaga qaraladi</th><th>Ball</th></tr></thead><tbody><tr><td>Tezkor nazorat /30</td><td>GoF 3 toifasi; Factory Method vazifasi; Singleton ishlashi va testdagi xatarlari</td><td></td></tr><tr><td>Amaliyot /30</td><td>Python&#39;da <code>__new__</code> orqali Singleton tuzish; <code>AppConfig</code> yagona nusxasini isbotlash</td><td></td></tr><tr><td>Ish sifati /20</td><td>Factory&#39;da noma&#39;lum turlar uchun istisno boshqaruvi; toza va ortiqcha yuklanmagan kod</td><td></td></tr><tr><td>Uyga vazifa /20</td><td><code>NotificationFactory</code> va <code>AppConfig</code> Singleton to&#39;liq yozilgan; PR ochilgan</td><td></td></tr><tr><td><strong>Jami /100</strong></td><td></td><td></td></tr></tbody></table><p>Izoh: ____________________</p><hr><h2 id="_3-hafta-yakuni-o-sish-dinamikasi" tabindex="-1">3-hafta yakuni: o&#39;sish dinamikasi <a class="header-anchor" href="#_3-hafta-yakuni-o-sish-dinamikasi" aria-label="Permalink to &quot;3-hafta yakuni: o&#39;sish dinamikasi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hafta</th><th>Darslar</th><th>O&#39;rtacha ball</th><th>Baho</th><th>Asosiy yutuq / Aniqlangan bo&#39;shliq</th></tr></thead><tbody><tr><td>1-hafta</td><td>1–3 (SDLC, Git)</td><td></td><td></td><td></td></tr><tr><td>2-hafta</td><td>4–6 (Branching, PR)</td><td></td><td></td><td></td></tr><tr><td>3-hafta</td><td>7–9 (SOLID, Patterns)</td><td></td><td></td><td></td></tr></tbody></table><p><strong>Mentor tavsiyasi:</strong> O&#39;quvchi professional backend arxitekturasining tamal toshlari bo&#39;lgan Clean Code, SOLID va Creational patternlarni to&#39;liq o&#39;zlashtirdi. Keyingi 4-haftada Observer andozasi orqali voqealarga asoslangan tizimlar hamda zamonaviy veb-xizmatlarning poydevori — REST API va JSON arxitekturasi o&#39;rganiladi.</p>',22))])])}const z=d(h,[["render",y]]);export{q as __pageData,z as default};
